'use client';
import { useState, useEffect, useMemo, use } from 'react';
import axios from 'axios';
import { 
  Save as SaveIcon,
  Clear as ClearIcon,
  Person as PersonIcon,
  Search as SearchIcon,
  Group as GroupIcon,
  ArrowBack as ArrowBackIcon
} from '@mui/icons-material';
import Layout from "@/components/Layout";
import Link from "next/link";

export default function EditGroupe({ params }) {
  // Properly unwrap the params promise
  const { id } = use(params);
  
  const [groupe, setGroupe] = useState(null);
  const [etudiants, setEtudiants] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedStudents, setSelectedStudents] = useState([]);
  const [availableStudents, setAvailableStudents] = useState([]);

  useEffect(() => {
    if (id) {
      fetchGroupeData();
    }
  }, [id]);

  const fetchGroupeData = async () => {
    try {
      setLoading(true);
      setError(null);
      
      const [groupeResponse, etudiantsResponse] = await Promise.all([
        axios.get(`/api/groupes/getgroupe/${id}`),
        axios.get('/api/etudiants')
      ]);

      setGroupe(groupeResponse.data);
      setSelectedStudents(groupeResponse.data.etudiants || []);
      
      // Filter students - available are those not in any group or already in this group
      const available = etudiantsResponse.data.filter(
        s => !s.idGroupe || s.idGroupe === id
      );
      
      setEtudiants(etudiantsResponse.data);
      setAvailableStudents(available);
    } catch (err) {
      console.error("Error fetching data:", err);
      setError("Failed to load group data. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  const handleAddStudent = (student) => {
    if (!selectedStudents.some(s => s.idEtudiant === student.idEtudiant)) {
      setSelectedStudents([...selectedStudents, student]);
    }
  };

  const handleRemoveStudent = (idEtudiant) => {
    setSelectedStudents(selectedStudents.filter(s => s.idEtudiant !== idEtudiant));
  };

  const handleSave = async () => {
    try {
      await axios.put(`/api/groupes/${id}/students`, {
        studentIds: selectedStudents.map(s => s.idEtudiant)
      });
      alert("Group updated successfully");
      fetchGroupeData(); // Refresh data
    } catch (err) {
      console.error("Error updating group:", err);
      alert("Error updating group: " + (err.response?.data?.message || err.message));
    }
  };

  const filteredStudents = useMemo(() => {
    if (!searchTerm.trim()) return availableStudents;
    const term = searchTerm.toLowerCase();
    return availableStudents.filter(e => 
      `${e.nom} ${e.prenom}`.toLowerCase().includes(term) ||
      `${e.prenom} ${e.nom}`.toLowerCase().includes(term)
    );
  }, [availableStudents, searchTerm]);

  if (loading) {
    return (
      <Layout title="Editing Group">
        <div className="flex justify-center items-center h-64">
          <p className="text-lg">Loading group data...</p>
        </div>
      </Layout>
    );
  }

  if (error) {
    return (
      <Layout title="Error">
        <div className="flex justify-center items-center h-64 flex-col">
          <p className="text-lg text-red-500 mb-4">{error}</p>
          <button 
            onClick={fetchGroupeData}
            className="px-4 py-2 bg-blue-500 text-white rounded hover:bg-blue-600"
          >
            Retry
          </button>
        </div>
      </Layout>
    );
  }

  if (!groupe) {
    return (
      <Layout title="Group Not Found">
        <div className="flex justify-center items-center h-64">
          <p className="text-lg">Group not found</p>
        </div>
      </Layout>
    );
  }

  return (
    <Layout title={`Editing ${groupe.nomGroupe}`}>
      <div className="p-4 max-w-7xl mx-auto">
        <div className="flex items-center mb-6">
          <Link href="/gestion-groupes" className="mr-4 text-blue-500 hover:text-blue-700">
            <ArrowBackIcon />
          </Link>
          <h1 className="text-2xl font-bold flex items-center">
            <GroupIcon className="mr-2" /> Editing Group: {groupe.nomGroupe}
          </h1>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
          {/* Available Students Column */}
          <div className="bg-white rounded-lg shadow p-4">
            <h2 className="text-xl font-semibold mb-4">Available Students</h2>
            
            <div className="mb-4 relative">
              <div className="absolute inset-y-0 left-0 flex items-center pl-3">
                <SearchIcon className="text-gray-400" />
              </div>
              <input
                type="text"
                placeholder="Search students..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full pl-10 p-2 border rounded focus:ring-2 focus:ring-blue-500 focus:outline-none"
              />
              {searchTerm && (
                <button
                  onClick={() => setSearchTerm('')}
                  className="absolute inset-y-0 right-0 flex items-center pr-3 text-gray-400 hover:text-gray-600"
                >
                  <ClearIcon />
                </button>
              )}
            </div>

            <div className="overflow-y-auto max-h-96 border rounded">
              {filteredStudents.length > 0 ? (
                <ul className="divide-y divide-gray-200">
                  {filteredStudents.map(student => (
                    <li 
                      key={student.idEtudiant}
                      className="p-3 hover:bg-blue-50 cursor-pointer flex justify-between items-center"
                      onClick={() => handleAddStudent(student)}
                    >
                      <div className="flex items-center">
                        <PersonIcon className="text-gray-400 mr-2" />
                        <span>{student.nom} {student.prenom}</span>
                      </div>
                      <button 
                        className="text-blue-500 hover:text-blue-700 text-sm"
                        onClick={(e) => {
                          e.stopPropagation();
                          handleAddStudent(student);
                        }}
                      >
                        Add
                      </button>
                    </li>
                  ))}
                </ul>
              ) : (
                <div className="p-4 text-center text-gray-500">
                  {searchTerm ? "No matching students found" : "No available students"}
                </div>
              )}
            </div>
          </div>

          {/* Selected Students Column */}
          <div className="bg-white rounded-lg shadow p-4">
            <h2 className="text-xl font-semibold mb-4">
              Group Members ({selectedStudents.length})
            </h2>
            
            <div className="overflow-y-auto max-h-96 border rounded">
              {selectedStudents.length > 0 ? (
                <ul className="divide-y divide-gray-200">
                  {selectedStudents.map(student => (
                    <li 
                      key={student.idEtudiant}
                      className="p-3 hover:bg-red-50 flex justify-between items-center"
                    >
                      <div className="flex items-center">
                        <PersonIcon className="text-blue-400 mr-2" />
                        <span>{student.nom} {student.prenom}</span>
                      </div>
                      <button 
                        onClick={() => handleRemoveStudent(student.idEtudiant)}
                        className="text-red-500 hover:text-red-700 text-sm"
                      >
                        Remove
                      </button>
                    </li>
                  ))}
                </ul>
              ) : (
                <div className="p-4 text-center text-gray-500">
                  No students in this group yet
                </div>
              )}
            </div>

            <div className="mt-4 flex justify-end space-x-3">
              <button
                onClick={handleSave}
                disabled={selectedStudents.length === 0}
                className={`px-4 py-2 rounded flex items-center ${
                  selectedStudents.length === 0
                    ? 'bg-gray-300 text-gray-500 cursor-not-allowed'
                    : 'bg-blue-600 text-white hover:bg-blue-700'
                }`}
              >
                <SaveIcon className="mr-2" /> Save Changes
              </button>
            </div>
          </div>
        </div>
      </div>
    </Layout>
  );
}